import { execSync } from 'node:child_process';
const CWD = '/home/user/rork-app';

try {
  // 1. Abort any merge, ensure clean
  try { execSync('git merge --abort', { cwd: CWD }); } catch(e) {}
  execSync('git checkout main', { cwd: CWD });
  execSync('git clean -fd', { cwd: CWD }); // remove untracked debris

  // 2. Fetch current GitHub main
  execSync('git fetch github main', { cwd: CWD });
  const fetchHead = execSync('git rev-parse FETCH_HEAD', { cwd: CWD, encoding: 'utf8' }).trim();
  console.log('GITHUB MAIN:', fetchHead.slice(0,12));

  // 3. Reset soft to GitHub main, staging all local changes
  execSync(`git reset --soft ${fetchHead}`, { cwd: CWD });
  const stagedStatus = execSync('git status --short', { cwd: CWD, encoding: 'utf8' }).trim();
  console.log('STAGED FILES:', stagedStatus.split('\n').length);

  // 4. Remove sensitive directories from the index
  execSync('git rm -r --cached .rork/history .gradle 2>&1 || true', { cwd: CWD, encoding: 'utf8' });

  // 5. Verify key files are still staged
  const postStatus = execSync('git status --short', { cwd: CWD, encoding: 'utf8' }).trim();
  console.log('POST STATUS sample:\n', postStatus.split('\n').slice(0,20).join('\n'));

  // 6. Commit
  execSync('git commit -m "IVX Twilio SMS fallback + chat UX cleanup (squashed)"', { cwd: CWD });
  const newHead = execSync('git rev-parse HEAD', { cwd: CWD, encoding: 'utf8' }).trim();
  console.log('NEW SQUASHED HEAD:', newHead.slice(0,12));

  // 7. Verify no history files in new commit
  const filesInCommit = execSync(`git diff-tree --no-commit-id --name-only -r ${newHead}`, { cwd: CWD, encoding: 'utf8' }).trim();
  const hasHistory = filesInCommit.split('\n').some(f => f.startsWith('.rork/history'));
  const hasGradle = filesInCommit.split('\n').some(f => f.startsWith('.gradle'));
  console.log('COMMIT CONTAINS HISTORY:', hasHistory);
  console.log('COMMIT CONTAINS GRADLE:', hasGradle);

  if (hasHistory || hasGradle) {
    console.error('Sensitive paths still in commit. Aborting push.');
    process.exit(1);
  }

  // 8. Force push with lease
  const pushOut = execSync(`git push github main --force-with-lease=main:${fetchHead} 2>&1`, { cwd: CWD, encoding: 'utf8', timeout: 120000 });
  console.log('PUSH:', pushOut);

  // 9. Verify parity
  const localHead = execSync('git rev-parse HEAD', { cwd: CWD, encoding: 'utf8' }).trim();
  const branchRes = await fetch('https://api.github.com/repos/ibb142/ivx-holdings-platform/branches/main', { headers: { 'User-Agent': 'ivx-deploy' } });
  const branchData = await branchRes.json();
  const ghSha = branchData.commit?.sha;
  console.log('PARITY:', localHead === ghSha ? 'YES' : 'NO', localHead.slice(0,12), 'vs', ghSha?.slice(0,12));

  // 10. Remove token from remote URL
  execSync('git remote set-url github https://github.com/ibb142/ivx-holdings-platform.git', { cwd: CWD });
  console.log('Remote URL token removed');

} catch (e) {
  console.error('ERROR:', e.stdout, e.stderr, e.message);
  process.exit(1);
}
EOF
